//! The app store over the core socket (F-SPLIT-03, D-SPLIT-03-STORE): `StoreApi` and `StorePublish` are generated by `dist/split/gen_rpc.py`
//! (one object, the supertrait's methods served through it); this file holds what the generator cannot write.
//!
//! The rules, all of them fail closed:
//! * the core's own fetch and audit stand in for the UI's (the argument leaves the signature, [`Registry::fetch`], [`Registry::audit`]);
//! * the person who acts is read again from the core's accounts by name (`Actor` and the policy never cross, [`Registry::actor`],
//!   [`Registry::policy_of`]); a name the core does not know is refused;
//! * a project folder the UI names is judged by the file rules of the machine's accounts before the core opens it ([`Registry::project_dir`]);
//! * a signing key never crosses: the UI holds a MARKER (a key made up here, worth nothing) that names the key by user and label, and the core
//!   loads the real key by that label for the one call that signs;
//! * the long call (`update_all`) is a job the UI polls.
#![allow(non_snake_case)] // the generator names the hand-written entry points c_<Trait>_<method>

use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, PoisonError};

use iyakki_agent_api::{StoreApi, UNAVAILABLE_STORE};
use iyakki_shared::store_catalog::{Fetch, Loaded, SourceCfg};
use iyakki_shared::store_install::Actor;
use iyakki_shared::store_keys::SigningKey;
use iyakki_shared::store_lifecycle::{Life, Report};
use iyakki_shared::store_license::Token;
use iyakki_shared::store_publishflow::{Card, Stop};
use iyakki_shared::store_author::Published;
use serde_json::{json, Value};

use crate::served::NOT_SERVED;
use crate::served_jobs::{finish_job, start_job};
use crate::{de, ser, Registry};

type Remote = crate::RemoteStoreApi;

// ---------------------------------------------------------------------------------------------------------------- what the core supplies

impl Registry<'_> {
    pub(crate) fn missing(what: &str) -> String {
        format!("{NOT_SERVED}: this core gave the socket no {what}")
    }

    /// The core's own way to fetch an address.
    pub(crate) fn fetch(&self) -> Result<Arc<dyn Fetch>, String> {
        self.side().fetch.ok_or_else(|| Self::missing("web fetch of its own"))
    }

    /// The audit line of the core.
    pub(crate) fn audit(&self) -> Arc<dyn Fn(&str, &str) + Send + Sync> {
        self.side().audit.unwrap_or_else(|| Arc::new(|_: &str, _: &str| {}))
    }

    /// The policy of the account `user`, read from the core's accounts.
    pub(crate) fn policy_of(&self, user: &str) -> Result<iyakki_sec::policy::Policy, String> {
        let accounts = self.side().accounts.ok_or_else(|| Self::missing("accounts"))?;
        accounts.get_public(user).map(|r| r.policy()).ok_or_else(|| format!("{NOT_SERVED}: there is no account {user}"))
    }

    /// Who is asking, as the core knows them (the role the UI may claim is never used).
    pub(crate) fn actor(&self, user: &str) -> Result<Actor, String> {
        self.policy_of(user).map(|p| Actor::from_policy(user, &p))
    }

    /// A folder the UI names, as the real path when some account of this machine may read (or write) it, else the sentence why not.
    pub(crate) fn project_dir(&self, dir: &Path, write: bool) -> Result<PathBuf, String> {
        let side = self.side();
        let accounts = side.accounts.ok_or_else(|| Self::missing("accounts"))?;
        let scope = side.file_scope.ok_or_else(|| Self::missing("file rules"))?;
        let real = std::fs::canonicalize(dir).map_err(|_| "that folder does not exist or is not allowed".to_string())?;
        let data = side.data_dir.unwrap_or_default();
        for rec in accounts.list_public() {
            let policy = rec.policy();
            let roots = scope.roots(&policy, &rec.name, &data);
            if roots.contains(&real) && if write { roots.write_ok(&policy, &rec.name, &real) } else { roots.read_ok(&policy, &rec.name, &real) } {
                return Ok(real);
            }
        }
        Err(format!("outside the folders {} on this machine", if write { "an account may write to" } else { "an account may read" }))
    }
}

// ---------------------------------------------------------------------------------------------------------------- the signing key marker

/// The markers the UI holds: (the marker's public key, user, label). A marker is a key made up here, so it signs nothing real; it only names the
/// key the core holds. The most recent 64 are kept.
static MARKERS: Mutex<Vec<([u8; 32], String, String)>> = Mutex::new(Vec::new());
static MARKER_COUNT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

fn marker(user: &str, label: &str) -> SigningKey {
    let n = MARKER_COUNT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let mut seed = [0u8; 32];
    seed[..8].copy_from_slice(&n.to_le_bytes());
    seed[8..16].copy_from_slice(b"ui-mark!");
    let key = SigningKey::from_bytes(&seed);
    let mut all = MARKERS.lock().unwrap_or_else(PoisonError::into_inner);
    all.push((key.verifying_key().to_bytes(), user.to_string(), label.to_string()));
    if all.len() > 64 {
        all.remove(0);
    }
    key
}

/// The user and label a marker names, when this is one of ours.
fn named_by(key: &SigningKey) -> Option<(String, String)> {
    let public = key.verifying_key().to_bytes();
    MARKERS.lock().unwrap_or_else(PoisonError::into_inner).iter().rev().find(|(p, _, _)| *p == public).map(|(_, u, l)| (u.clone(), l.clone()))
}

fn load_key(t: &Arc<dyn StoreApi>, user: &str, label: &str) -> Result<(SigningKey, String), String> {
    t.keys_load(user, Some(label)).ok_or_else(|| format!("there is no signing key called {label} for {user}"))
}

// ---------------------------------------------------------------------------------------------------------------- the UI's end (`c_`)

/// A lookup in the lives the caller holds: no call at all.
pub(crate) fn c_StoreApi_find_life<'a>(_s: &Remote, lives: &'a [Life], id: &str) -> Result<&'a Life, String> {
    iyakki_shared::store_lifecycle::find_life(lives, id)
}

pub(crate) fn c_StoreApi_add_license(s: &Remote, actor: &Actor, text: &str, _signer_of: &dyn Fn(&str) -> Vec<String>) -> Result<Token, String> {
    s.rpc.call::<Result<Token, String>>("StoreApi", s.obj, "add_license", json!([actor.user, text])).map_err(|e| format!("{NOT_SERVED}: {e}"))?
}

pub(crate) fn c_StoreApi_update_all(s: &Remote, _policy: &iyakki_sec::policy::Policy, user: &str, loaded: &[Loaded], _fetch: &dyn Fetch, _audit: &dyn Fn(&str, &str), progress: &mut dyn FnMut(&str)) -> Report {
    finish_job::<Report>(&s.rpc, s.rpc.call::<u64>("StoreApi", s.obj, "update_all", json!([user, loaded])), progress)
}

/// The key is not sent: the core says which label it chose and the UI holds a marker for it.
pub(crate) fn c_StoreApi_keys_load(s: &Remote, user: &str, label: Option<&str>) -> Option<(SigningKey, String)> {
    let chosen = s.rpc.call::<Option<String>>("StoreApi", s.obj, "keys_load", json!([user, label])).ok().flatten()?;
    Some((marker(user, &chosen), chosen))
}

pub(crate) fn c_StoreApi_pf_card(s: &Remote, user: &str, dir: &Path, src: &SourceCfg, key: &(SigningKey, String), _fetch: &dyn Fetch) -> Result<(Card, String), String> {
    s.rpc.call::<Result<(Card, String), String>>("StoreApi", s.obj, "pf_card", json!([user, dir, src, key.1])).map_err(|e| format!("{NOT_SERVED}: {e}"))?
}

pub(crate) fn c_StoreApi_pf_publish(s: &Remote, user: &str, dir: &Path, src: &SourceCfg, key: Option<&(SigningKey, String)>, _fetch: &dyn Fetch, now: i64) -> Result<Published, Stop> {
    let label = key.map(|k| k.1.clone());
    s.rpc.call::<Result<Published, Stop>>("StoreApi", s.obj, "pf_publish", json!([user, dir, src, label, now])).unwrap_or_else(|e| Err(Stop::Refused(format!("{NOT_SERVED}: {e}"))))
}

pub(crate) fn c_StoreApi_author_pack_dir(s: &Remote, dir: &Path, key: Option<&SigningKey>) -> Result<(String, Vec<String>), String> {
    // a key that is not one of our markers is a real key of the UI's own: it is never sent, the pack is made unsigned
    let named = key.and_then(named_by);
    s.rpc.call::<Result<(String, Vec<String>), String>>("StoreApi", s.obj, "author_pack_dir", json!([dir, named])).map_err(|e| format!("{NOT_SERVED}: {e}"))?
}

pub(crate) fn c_StoreApi_official_store_url(s: &Remote) -> Option<&'static str> {
    s.rpc.call::<Option<String>>("StoreApi", s.obj, "official_store_url", json!([])).ok().flatten().map(crate::handle::intern)
}

pub(crate) fn c_StoreApi_pf_yank_note(s: &Remote) -> &'static str {
    s.rpc.call::<String>("StoreApi", s.obj, "pf_yank_note", json!([])).map(crate::handle::intern).unwrap_or("")
}

// ---------------------------------------------------------------------------------------------------------------- the core's end (`s_`)

pub(crate) fn s_StoreApi_find_life(_t: &Arc<dyn StoreApi>, _reg: &Registry<'_>, _a: Value) -> Result<Value, String> {
    Err("find_life is a lookup in the caller's own lives and needs no call".into())
}

/// The signers are the core's own: its catalogs' items, as the store page lists them for this person.
pub(crate) fn s_StoreApi_add_license(t: &Arc<dyn StoreApi>, reg: &Registry<'_>, a: Value) -> Result<Value, String> {
    let (user, text): (String, String) = de(a)?;
    let actor = reg.actor(&user)?;
    let items = t.items(&actor, &t.local_catalogs());
    ser(&t.add_license(&actor, &text, &|app| items.iter().filter(|i| i.entry.name == app && !i.entry.signer.is_empty()).map(|i| i.entry.signer.clone()).collect()))
}

pub(crate) fn s_StoreApi_update_all(t: &Arc<dyn StoreApi>, reg: &Registry<'_>, a: Value) -> Result<Value, String> {
    let (user, loaded): (String, Vec<Loaded>) = de(a)?;
    let policy = reg.policy_of(&user)?;
    let (fetch, audit) = (reg.fetch()?, reg.audit());
    let t = t.clone();
    start_job(reg, move |say| {
        let report = t.update_all(&policy, &user, &loaded, &*fetch, &*audit, &mut |l| {
            say(l);
        });
        serde_json::to_value(report).unwrap_or(Value::Null)
    })
}

/// Which key the core would use; the key itself stays here.
pub(crate) fn s_StoreApi_keys_load(t: &Arc<dyn StoreApi>, _reg: &Registry<'_>, a: Value) -> Result<Value, String> {
    let (user, label): (String, Option<String>) = de(a)?;
    ser(&t.keys_load(&user, label.as_deref()).map(|(_, chosen)| chosen))
}

pub(crate) fn s_StoreApi_pf_card(t: &Arc<dyn StoreApi>, reg: &Registry<'_>, a: Value) -> Result<Value, String> {
    let (user, dir, src, label): (String, PathBuf, SourceCfg, String) = de(a)?;
    reg.policy_of(&user)?;
    let dir = reg.project_dir(&dir, false)?;
    let key = load_key(t, &user, &label)?;
    ser(&t.pf_card(&user, &dir, &src, &key, &*reg.fetch()?))
}

pub(crate) fn s_StoreApi_pf_publish(t: &Arc<dyn StoreApi>, reg: &Registry<'_>, a: Value) -> Result<Value, String> {
    let (user, dir, src, label, now): (String, PathBuf, SourceCfg, Option<String>, i64) = de(a)?;
    reg.policy_of(&user)?;
    let dir = reg.project_dir(&dir, false)?;
    let key = match label {
        Some(l) => Some(load_key(t, &user, &l)?),
        None => None,
    };
    ser(&t.pf_publish(&user, &dir, &src, key.as_ref(), &*reg.fetch()?, now))
}

pub(crate) fn s_StoreApi_author_pack_dir(t: &Arc<dyn StoreApi>, reg: &Registry<'_>, a: Value) -> Result<Value, String> {
    let (dir, named): (PathBuf, Option<(String, String)>) = de(a)?;
    let dir = reg.project_dir(&dir, false)?;
    let key = match named {
        Some((user, label)) => {
            reg.policy_of(&user)?;
            Some(load_key(t, &user, &label)?.0)
        }
        None => None,
    };
    ser(&t.author_pack_dir(&dir, key.as_ref()))
}

pub(crate) fn s_StoreApi_official_store_url(t: &Arc<dyn StoreApi>, _reg: &Registry<'_>, _a: Value) -> Result<Value, String> {
    ser(&t.official_store_url())
}

pub(crate) fn s_StoreApi_pf_yank_note(t: &Arc<dyn StoreApi>, _reg: &Registry<'_>, _a: Value) -> Result<Value, String> {
    ser(&t.pf_yank_note())
}

#[allow(dead_code)]
const _: &str = UNAVAILABLE_STORE;
